print('A Hdim',len(ker),'imageD',len(images));hist={}
for bits in range(1<<len(images)):
 v=0
 for j,h in enumerate(images):
  if bits>>j&1:v^=h
 hist[v.bit_count()]=hist.get(v.bit_count(),0)+1
print('A image histogram',hist);assert 24 not in hist
